  VALUES (m, match_school(m), 'firm', 'light', 'even', 'medium', 'batting', false, 'Rolled Thursday, mown to 6 mm. True bounce; quick outfield.', 6, 6, 'fast', app_user_id(), now())
  ON CONFLICT (match_id) DO NOTHING;
