  ON CONFLICT (match_id) DO NOTHING;
  IF (SELECT count(*) FROM match_squad q WHERE q.match_id = m AND q.side = 'home' AND NOT q.withdrawn) < 11 THEN
  PERFORM app_session_begin((ids->>'coach.wes.u14a@example.invalid')::uuid, 'demo-season', NULL, NULL);
    SELECT count(*) INTO n FROM match mt CROSS JOIN unnest(ARRAY['de300000-0000-4000-8000-000000000106', 'de300000-0000-4000-8000-000000000110', 'de300000-0000-4000-8000-000000000112', 'de300000-0000-4000-8000-000000000113', 'de300000-0000-4000-8000-000000000115', 'de300000-0000-4000-8000-000000000109', 'de300000-0000-4000-8000-000000000107', 'de300000-0000-4000-8000-000000000108', 'de300000-0000-4000-8000-000000000111', 'de300000-0000-4000-8000-000000000114', 'de300000-0000-4000-8000-000000000116']::uuid[]) p(id) JOIN player pl ON pl.id = p.id
     WHERE mt.id = m AND pl.school_id = mt.school_id
       AND app_can('team.select', pl.school_id, mt.team_code, p.id, mt.id);
    IF n <> 11 THEN RAISE EXCEPTION 'WES U14A coach may not name his XI for u14a-1015 (% of 11). Nothing was changed.', n; END IF;
