    ON CONFLICT (match_id, player_id) DO UPDATE SET side = excluded.side, batting_no = excluded.batting_no, twelfth = false,
       withdrawn = false, selected_by = excluded.selected_by, selected_at = excluded.selected_at;
  END IF;
  IF (SELECT count(*) FROM match_squad q WHERE q.match_id = m AND q.side = 'away' AND NOT q.withdrawn) < 11 THEN
  PERFORM app_session_begin((ids->>'coach.kea.u14a@example.invalid')::uuid, 'demo-season', NULL, NULL);
    SELECT count(*) INTO n FROM match mt CROSS JOIN unnest(ARRAY['de300000-0000-4000-8000-000000000271', 'de300000-0000-4000-8000-000000000272', 'de300000-0000-4000-8000-000000000274', 'de300000-0000-4000-8000-000000000275', 'de300000-0000-4000-8000-000000000280', 'de300000-0000-4000-8000-000000000281', 'de300000-0000-4000-8000-000000000277', 'de300000-0000-4000-8000-000000000278', 'de300000-0000-4000-8000-000000000279', 'de300000-0000-4000-8000-000000000273', 'de300000-0000-4000-8000-000000000276']::uuid[]) p(id) JOIN player pl ON pl.id = p.id
     WHERE mt.id = m AND pl.school_id = mt.away_school_id
       AND app_can('team.select', pl.school_id, mt.away_team_code, p.id, mt.id);
